{#- ------ Macros Start ----- -#}

{%- macro html_output(html_title, source_datum, list_wrapper, markdown, rich) -%}
 {% set list_wrapper = list_wrapper|default("p") %}
 {% set markdown = markdown|default(false) %}
 {% set rich = rich|default(false) %}
  {# Handle Drupal-style objects with a "value" property #}


  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}
 
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
     <{{ list_wrapper }}>{{ html_title }}</{{ list_wrapper }}>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          {{ source_data|markdown_2_html }}
        {%- else -%}
          {%- if rich -%}
            <{{ list_wrapper }}>{{ source_data|raw }}</{{ list_wrapper }}>
          {%- else -%}
            <{{ list_wrapper }}>{{ source_data|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        {{ source_datum|markdown_2_html }}
      {%- else -%}
        {%- if rich -%}
          {%- if list_wrapper|length > 0 -%}
            <{{ list_wrapper }}>{{ source_datum|raw }}</{{ list_wrapper }}>
          {%- else -%}
            {{ source_datum|raw }}
          {%- endif -%}
          {%- else -%}
          <{{ list_wrapper }}>{{ source_datum|striptags }}</{{ list_wrapper }}>
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
      </div>
    </div>
  {%- endif -%}
   
{%- endmacro html_output -%}


{%- macro html_output_list(html_title, source_datum, markdown, rich) -%}
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
 {% set markdown = markdown|default(false) %}
 {% set rich = rich|default(false) %}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          <li>{{ source_data|markdown_2_html }}</li>
        {%- elseif rich -%}
          <li>{{ source_data|raw }}</li>
        {%- else -%}
         <li>{{ source_data|striptags }}</li>
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        <li>{{ source_datum|markdown_2_html }}</li>
       {%- elseif rich -%}  
         <li>{{ source_datum|raw }}</li>
      {%- else -%}
        <li>{{ source_datum|striptags }}</li>
      {%- endif -%}
    {%- endif -%}
      </ul>
    </div>
  </div>
  {%- endif -%}
{%- endmacro html_output_list -%}


{# Allison: internal search macros based off Diego's list output macro above;
added flag and formatting for internal search-based on value set within corresponding facet config;
one macro for simple non-LoD elements; second for LoD elements with URI and label values #}

{%- macro html_output_search(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_data|url_encode }}" target="_blank">{{ source_data }}</a></li>
      {%- endfor -%}
    {%- else -%}
      <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_datum|url_encode }}" target="_blank">{{ source_datum }}</a></li>
    {%- endif -%}
      </ul>
    </div>
  </div>    
  {%- endif -%}
{%- endmacro html_output_search -%}


{# Use for LoD elements with URI and label values #}
{%- macro html_output_search_lod(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
  <div class="row border-1 mx-1 border-bottom">
    <div class="col-3 fw-light">  
    {%- if html_title|length > 0 -%}
      <p>{{ html_title }}</p>
    {%- endif -%}
    </div>
    <div class="col-9 fw-light">
      <ul>
    {%- for source_data in source_datum -%}
      <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_data.label|url_encode }}" target="_blank">{{ source_data.label }}</a></li>
    {%- endfor -%}
      </ul>
    </div>
  </div>  
  {%- endif -%}
{%- endmacro html_output_search_lod -%}

{#- --- End Macros ---- -#}


{# Alternative relationship display section carried over from legacy template 24, section originally created by DP.
commented out for now, can be uncommented and swapped for above less-complex relationship mapping section if needed.
#}

{% set possible_predicates = ["ismemberof","ispartof","ismemberofseries", "ismemberofcollection"] %}
{% set accumulated_links_per_predicate = [] %}
{% for predicate in possible_predicates %}
  {% if attribute(data, predicate)  %} 
    {% if attribute(data, predicate) is iterable %} 
	  {% for parent_id in attribute(data, predicate)%} 
        {% if parent_id is instanceof("numeric") %}
		  {% set parentnode = bamboo_load_entity('node', parent_id) %} 
          {% if parentnode %}
            {% set parentnode_type = parentnode.field_descriptive_metadata.0.value|sbf_json_decode %}
            {% set parentnode_type = "" ~ (parentnode_type['type'] is iterable ? parentnode_type['type'][0] : parentnode_type['type']) %}
		    {% set parentnodeurl = url('entity.node.canonical', {'node': parentnode.id}, {'absolute': true}) %} 
			  {# first check if we have a parent type first #}
              {% set link = '<a href="' ~ parentnodeurl|render ~ '">' ~ parentnode.title.value ~ '</a>' %}
              {% if accumulated_links_per_predicate[parentnode_type] is not empty and link not in accumulated_links_per_predicate[parentnode_type] %}
                {% set accumulated_links_per_predicate = accumulated_links_per_predicate|merge(accumulated_links_per_predicate[parentnode_type]|merge([link])) %}
              {% elseif accumulated_links_per_predicate[parentnode_type] is not defined %}
                {% set accumulated_links_per_predicate = accumulated_links_per_predicate|merge({(parentnode_type):[link]}) %} 
              {% endif %} 
           {% endif %}
        {% endif %}   
	  {% endfor %} 
    {% else %} 
      {% if attribute(data, predicate) is instanceof("numeric") %}
	    {% set parentnode = bamboo_load_entity('node', attribute(data, predicate)) %} 
        {% if parentnode %} 
          {% set parentnode_type = parentnode.field_descriptive_metadata.0.value|sbf_json_decode %}
          {% set parentnode_type = "" ~ (parentnode_type['type'] is iterable ? parentnode_type['type'][0] : parentnode_type['type']) %}
		  {% set parentnodeurl = url('entity.node.canonical', {'node': attribute(data, predicate)}, {'absolute': true}) %}
            {% set link = '<a href="' ~ parentnodeurl|render ~ '">' ~  parentnode.title.value ~ '</a>' %}
            {% if accumulated_links_per_predicate[parentnode_type] is not empty and link not in accumulated_links_per_predicate[parentnode_type] %}
               {% set accumulated_links_per_predicate = accumulated_links_per_predicate|merge(accumulated_links_per_predicate[parentnode_type]|merge([link])) %}
            {% elseif accumulated_links_per_predicate[parentnode_type] is not defined %}
                {% set accumulated_links_per_predicate = accumulated_links_per_predicate|merge({(parentnode_type):[link]}) %} 
            {% endif %}  
        {% endif %} 
      {% endif %} 
    {% endif %}
  {% endif %}
{% endfor %}
{% if accumulated_links_per_predicate is iterable and not empty %}
  {% for title,links in accumulated_links_per_predicate %}
  {{ _self.html_output(title, links,  list_wrapper = "p", markdown = false, rich = true) }}
  {% endfor %}
{% endif %}

{# End of enclosing comments for alternative relationship display section #}


{{ _self.html_output("Title", data.label) }}
{{ _self.html_output("Alternative Title", data.label_alt) }}  
