{% if data.descriptions|length > 0 %}
<div class="accordion">
  {% for description in data.descriptions %}
    {% set accordeon_title = "Other Description Info" %}
    {% if description.description_type|default('')|lower in ['abstract','transcript'] %}
      {% set accordeon_title =  description.description_type|capitalize %}
    {% endif %}
  <div class="accordion-item bg-transparent text-black fw-light border-0 row border-1 mx-1 border-bottom">  
    {# Diego: This will disable collapsing if the description is short #}
    {% if description.description|default('')|markdown_2_html|length > 350 %} 
        <div class="accordion-header text-black col-3 ">
           <button class="px-0 accordion-button collapsed rounded-0 border-0 bg-transparent text-black" type="button" data-bs-toggle="collapse" data-bs-target="#collapseBody{{loop.index}}">
             <span class="py-2 text-black">{{ accordeon_title }}</span>
          </button>
       </div>
       <div id="collapseBody{{loop.index}}" class="accordion-collapse collapse col-9">
         <div class="accordion-body px-0 text-black pt-0">
      {{ description.description|markdown_2_html }}
        </div>
      </div> 
  {% else %}
    <div class="col-3">
     <div class="py-2 fw-light">{{ accordeon_title }}</div>
    </div>
    <div class="col-9">
      <div class="fw-light">
      {{ description.description|markdown_2_html }}
      </div>
    </div> 
  {% endif %}
   </div> 
 {% endfor %} 
 </div>
{% endif %}   

{% if data.dates_edtf|length > 0 %}
